197	/**
198	 * Merges a partial sanitization config with secure defaults and validates it.
199	 * This ensures that sensitive environment variables cannot be bypassed by
200	 * request-provided configurations.
201	 */
202	export function getSecureSanitizationConfig(
203	  requestedConfig: Partial<EnvironmentSanitizationConfig> = {},
204	  baseConfig?: EnvironmentSanitizationConfig,
205	): EnvironmentSanitizationConfig {
206	  const allowed = [
207	    ...(baseConfig?.allowedEnvironmentVariables ?? []),
208	    ...(requestedConfig.allowedEnvironmentVariables ?? []),
209	  ].filter((key) => {
210	    const upperKey = key.toUpperCase();
211	    // Never allow variables that are explicitly forbidden by name
212	    if (NEVER_ALLOWED_ENVIRONMENT_VARIABLES.has(upperKey)) {
213	      return false;
214	    }
215	    // Never allow variables that match sensitive name patterns
216	    for (const pattern of NEVER_ALLOWED_NAME_PATTERNS) {
217	      if (pattern.test(upperKey)) {
218	        return false;
219	      }
220	    }
221	    return true;
222	  });
223	
224	  const blocked = [
225	    ...(baseConfig?.blockedEnvironmentVariables ?? []),
226	    ...(requestedConfig.blockedEnvironmentVariables ?? []),
227	  ];
228	
229	  return {
230	    allowedEnvironmentVariables: [...new Set(allowed)],
231	    blockedEnvironmentVariables: [...new Set(blocked)],
232	    // Redaction must be enabled for secure configurations
233	    enableEnvironmentVariableRedaction: true,
234	  };
235	}
